"use client";

import { motion } from "motion/react";
import { useState } from "react";

const STAR = "M12 2.75l2.83 5.73 6.32.92-4.57 4.46 1.08 6.3L12 17.18l-5.66 2.98 1.08-6.3L2.85 9.4l6.32-.92L12 2.75z";

export function StarRatingTailwind() {
  const [value, setValue] = useState(3.5);
  const [hover, setHover] = useState<number | null>(null);
  const shown = hover ?? value;
  const at = (e: React.PointerEvent | React.MouseEvent, i: number) => {
    const r = (e.currentTarget as HTMLElement).getBoundingClientRect();
    return e.clientX - r.left < r.width / 2 ? i + 0.5 : i + 1;
  };
  const onKey = (e: React.KeyboardEvent) => {
    const d = e.key === "ArrowRight" || e.key === "ArrowUp" ? 0.5 : e.key === "ArrowLeft" || e.key === "ArrowDown" ? -0.5 : 0;
    if (!d) return;
    e.preventDefault();
    setValue((v) => Math.min(5, Math.max(0, v + d)));
  };
  return (
    <div role="slider" tabIndex={0} aria-label="Rating" aria-valuemin={0} aria-valuemax={5} aria-valuenow={value} aria-valuetext={`${value} out of 5 stars`} onKeyDown={onKey} onPointerLeave={() => setHover(null)} className="inline-flex gap-1.5 rounded-lg outline-none focus-visible:ring-2 focus-visible:ring-zinc-200">
      {[0, 1, 2, 3, 4].map((i) => (
        <motion.span key={i} aria-hidden animate={{ scale: hover !== null && Math.ceil(hover) === i + 1 ? 1.15 : 1 }} onPointerMove={(e) => setHover(at(e, i))} onClick={(e) => setValue(at(e, i))} className="relative size-8 cursor-pointer">
          <svg viewBox="0 0 24 24" className="size-8 fill-zinc-800 stroke-zinc-600"><path d={STAR} /></svg>
          <span className="absolute inset-y-0 left-0 overflow-hidden" style={{ width: `${Math.max(0, Math.min(1, shown - i)) * 100}%` }}>
            <svg viewBox="0 0 24 24" className="size-8 max-w-none fill-amber-500 stroke-amber-500"><path d={STAR} /></svg>
          </span>
        </motion.span>
      ))}
    </div>
  );
}
